from pathlib import Path
import sys,json,subprocess,wave,hashlib,base64,html,struct
R=Path.cwd();D=R/'build/dialogue-extracts/folie-des-grandeurs';sys.path.insert(0,str(R/'build/audio-tools'));import imageio_ffmpeg
url='https://www.fufuworld.com/data/contents/common/sounds/grandeurs/folie-grandeurs-02-flatterie.mp3';text='Est-ce que vous pensez vraiment ce que vous dites ?';start=56.28;end=59.5;wav=D/'pensez-vraiment-ce-que-vous-dites.wav';mp3=wav.with_suffix('.mp3')
f=f'atrim=start={start}:end={end},asetpts=PTS-STARTPTS,loudnorm=I=-18:TP=-2:LRA=9,afade=t=in:d=0.005,afade=t=out:st={end-start-.012}:d=0.012,adelay=220:all=1'
subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-hide_banner','-loglevel','error','-y','-i',str(D/'source.mp3'),'-af',f,'-ar','44100','-ac','1','-c:a','pcm_s16le',str(wav)],check=True,capture_output=True)
subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-hide_banner','-loglevel','error','-y','-i',str(wav),'-c:a','libmp3lame','-b:a','128k',str(mp3)],check=True,capture_output=True)
with wave.open(str(wav)) as w:
 duration=round(w.getnframes()/w.getframerate(),3);samples=struct.unpack('<'+'h'*w.getnframes(),w.readframes(w.getnframes()));assert max(abs(x) for x in samples[:round(.18*44100)])<200;assert max(abs(x) for x in samples)>1000
r=dict(text=text,film='La Folie des grandeurs',sourceUrl=url,startSeconds=start,endSeconds=end,durationSeconds=duration,wavFile=wav.name,mp3File=mp3.name,sha256=hashlib.sha256(wav.read_bytes()).hexdigest(),mp3Sha256=hashlib.sha256(mp3.read_bytes()).hexdigest(),changes='Original voices retained. Mono PCM 44.1 kHz, -18 LUFS / -2 dBTP target, 220 ms protected lead-in, 5 ms fade-in and 12 ms fade-out; MP3 128 kbps copy.',status='extracted_for_review',usage='Private local extraction from user-provided source; no redistribution permission asserted')
(D/'dialogue.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
data=base64.b64encode(mp3.read_bytes()).decode();page='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>La Folie des grandeurs — extrait</title><style>*{box-sizing:border-box}body{max-width:860px;margin:35px auto;padding:0 20px;background:#101827;color:#eef4ff;font:18px/1.5 system-ui}h1{font-size:32px;line-height:1.2}article{padding:24px;background:#20314a;border:1px solid #40516c;border-radius:14px;margin:24px 0}h2{font-size:25px;line-height:1.45}audio{width:100%;margin:15px 0}a{color:#a4d8ff}.meta{font-size:15px;color:#bccbdd}</style><h1>La Folie des grandeurs</h1><article><h2>'''+html.escape(text)+'''</h2><audio controls preload="none" src="data:audio/mpeg;base64,'''+data+'''"></audio><p><a download href="./'''+wav.name+'''">Télécharger WAV</a> · <a download href="./'''+mp3.name+'''">Télécharger MP3</a></p><p class="meta">Durée : '''+str(duration)+''' s · source : 56,28–59,50 s.</p></article><p><a href="'''+url+'''">Écouter la source</a></p><p class="meta">Voix d’origine, volume harmonisé et courte amorce pour protéger les premiers mots. Extrait préparé pour écoute ; la banque du jeu n’a pas été modifiée.</p></html>'''
(D/'index.html').write_text(page,encoding='utf8');print('Exported WAV/MP3 and offline preview:',duration,'seconds.')
